        'MEDICO',
        'RECEPCAO',
        'ADMIN_CLINICA',
        'technical-admin,agency-admin,field-agent,rait-coordinator,dash-operator',
      ],
    );
    for (const restart of restarts.filter(({ roles }) => roles !== 'MEDICO')) {
      assert.equal(
