      assert.equal(restart.actorValue, '');
    }
    assert.deepEqual(restarts[4], {
      roles: 'MEDICO',
      actorState: 'present',
      actorValue: '00000000-0000-4000-8000-0000b0000002',
    });
  } finally {
    rmSync(stateDir, { recursive: true, force: true });
    rmSync(bin, { recursive: true, force: true });
  }
});

